export default {
  id: 'factor-base',
  name: 'Factor Base',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'service',
      service: { id: 'factor', instance: { value: 7 } }
    });
  }
};

export default {
  id: 'factor-consumer',
  name: 'Factor Consumer',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    const injected = ctx.inject('service:factor');
    const factor = injected.value as { value: number };
    ctx.register({
      kind: 'command',
      command: {
        name: 'multiply',
        description: 'Return factor value multiplied by 5 as a string.',
        handler: async () => String(factor.value * 5)
      }
    });
  }
};

